import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"30、【离】 离下离上","description":"周易口诀义 - 30、【离】 离下离上","frontmatter":{"title":"30、【离】 离下离上","description":"周易口诀义 - 30、【离】 离下离上"},"headers":[],"relativePath":"zh/classics/koujueyi/032.md","filePath":"zh/classics/koujueyi/032.md"}'),r={name:"zh/classics/koujueyi/032.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_30、【离】-离下离上" tabindex="-1">30、【离】 离下离上 <a class="header-anchor" href="#_30、【离】-离下离上" aria-label="Permalink to “30、【离】 离下离上”">​</a></h1><p>彖曰：离，丽也。日月丽乎天，百谷草木丽乎土，重明以丽乎正，乃化成天下。柔丽乎中正，故亨，是以「畜牝牛吉」也。</p><p>象曰：明两作，离。大人以继明照于四方。</p><p>初九：履错然，敬之，无咎。</p><p>象曰：「履错」之「敬」，以辟咎也。</p><p>六二：黄离，元吉。</p><p>象曰：「黄离元吉」，得中道也。</p><p>九三：日昃之离，不鼓缶而歌，则大耋之嗟，凶。</p><p>象曰：「日昃之离」，何可久也。</p><p>九四：突如其来如，焚如，死如，弃如。</p><p>象曰：「突如其来如」，无所容也。</p><p>六五：出涕沱若，戚嗟若，吉。</p><p>象曰：六五之吉，离王公也。</p><p>上九：王用出征，有嘉折首，获匪其丑，无咎。</p><p>象曰：「王用出征」，以正邦也。</p><p>解读</p><p>「离利贞亨」者，「离」，丽也，柔著于中正，柔而处中，恐陷邪謟，邪謟则不获亨通，故须利贞正后乃得通，故「利贞亨」。丽犹著也，如出著于物也。「畜牝牛吉」者，畜，养也，牛者外强内顺，然离之为体，故不可养刚猛之物，则可畜养牝牛，牛者顺从之物而又牝焉。象曰「明两作，离」者，上下重明相照，故云「明两作，离」也。故东宫有重明门，欲令太子续于明也。「大人以继明照于四方」者，继明犹「缉熙」之义。</p><p>「初九，履错然，敬之，无咎」者，履而错然，谓不安之貌也。初九处无位之地，心常不安，常虑危害，若能恭敬为本，以避于害，即得「无咎」，故曰「敬之，无咎」也。</p><p>「六二，黄离，元吉」者，「黄」，中色也；「离」，文明也；得黄中之色，而又处文明，故复大吉也。</p><p>「九三，日昃之离，不鼓缶而歌，则大耋之嗟，凶」者，处下卦之上，如日昃之离，喻人中年以上，可委政于人，求己之乐；鼓缶而歌，乐天知命而已。若不知天命，独亲执政事，至于耋老嗟怨，无益，所以「凶」也。</p><p>「九四，突如其来如，焚如，死如，弃如」者，三处下离已没之际，四为上离始出之初，「突如」始出，忽然而来，故曰「突如其来如」；欲进炎而焚于君，故曰「焚如」；以臣害君，命必不全，故曰「死如」也；违于臣节，众之所弃，故曰「弃如」也。</p><p>「六五：出涕沱若，戚嗟若，吉」者，阴居阳位，不胜所履，四为逆首，欲来害己，若其出涕沱，忧戚嗟，如此戒惧，为众所助，乃得「吉」也。</p><p>「上九：王用出征，有嘉折首，获匪其丑，无咎」者，处离之极，离道已盛，则须除其非类以去民害。故王用出征伐，必有嘉美之功，折断罪人之首，获得非类者，始可免咎。以处穷极之地，当须去民之害，乃得「无咎」，故曰「获匪其丑，无咎」也。丑，类也。周易口诀义卷三，</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
